namespace SmallRepo;

public static class OrderDiscount
{
    public static decimal Apply(IEnumerable<Order> orders, decimal rate)
    {
        decimal total = 0m;
        foreach (var order in orders)
        {
            total += order.Amount * (1m - rate);
        }
        return total;
    }
}

